const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "..");
const outputDirectory = path.join(projectRoot, "content", "bundles");

function jsonFiles(directory, output = []) {
  const entries = fs
    .readdirSync(directory, { withFileTypes: true })
    .sort((left, right) => left.name.localeCompare(right.name));

  for (const entry of entries) {
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      jsonFiles(fullPath, output);
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith(".json")) {
      output.push(fullPath);
    }
  }

  return output;
}

function buildBundle(sourceRelativePath, outputFileName) {
  const sourceDirectory = path.join(projectRoot, sourceRelativePath);
  const items = [];

  for (const file of jsonFiles(sourceDirectory)) {
    const value = JSON.parse(fs.readFileSync(file, "utf8"));
    if (Array.isArray(value)) items.push(...value);
    else items.push(value);
  }

  const outputPath = path.join(outputDirectory, outputFileName);
  const nextContents = `${JSON.stringify(items)}\n`;
  const currentContents = fs.existsSync(outputPath)
    ? fs.readFileSync(outputPath, "utf8")
    : null;

  if (currentContents !== nextContents) {
    fs.writeFileSync(outputPath, nextContents, "utf8");
    console.log(`Updated ${path.relative(projectRoot, outputPath)} (${items.length} items)`);
  } else {
    console.log(`Unchanged ${path.relative(projectRoot, outputPath)} (${items.length} items)`);
  }
}

function buildBibleLoaderRegistry() {
  const sourceDirectory = path.join(projectRoot, "content", "bible", "versions");
  const outputPath = path.join(
    projectRoot,
    "src",
    "generated",
    "bibleVersionLoaders.ts"
  );
  const files = jsonFiles(sourceDirectory).map((file) =>
    path.relative(sourceDirectory, file).replaceAll("\\", "/")
  );
  const entries = files.map(
    (file) =>
      `  ${JSON.stringify(file)}: () => import(${JSON.stringify(
        `../../content/bible/versions/${file}`
      )}),`
  );
  const nextContents = [
    "// Generated by scripts/build-content-bundles.js. Do not edit by hand.",
    "export const bundledBibleLoaders: Record<string, () => Promise<any>> = {",
    ...entries,
    "};",
    "",
  ].join("\n");

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  const currentContents = fs.existsSync(outputPath)
    ? fs.readFileSync(outputPath, "utf8")
    : null;
  if (currentContents !== nextContents) {
    fs.writeFileSync(outputPath, nextContents, "utf8");
    console.log(`Updated ${path.relative(projectRoot, outputPath)} (${files.length} versions)`);
  } else {
    console.log(`Unchanged ${path.relative(projectRoot, outputPath)} (${files.length} versions)`);
  }
}

fs.mkdirSync(outputDirectory, { recursive: true });
buildBundle(path.join("content", "songs"), "songs.json");
buildBundle(path.join("content", "studies"), "studies.json");
buildBibleLoaderRegistry();
